        var twoLifted=SidebarLayout.arrange(split,true,true,66);
        CoreTests.check(twoLifted.tyres().bottom()==402&&twoLifted.phone().bottom()==402&&twoLifted.tyres().right()==633&&SidebarLayout.arrange(split.withOrder(List.of(WidgetSettings.PHONE,WidgetSettings.NOTIFICATIONS,WidgetSettings.MUSIC,WidgetSettings.COLUMN_DIVIDER,WidgetSettings.TYRES)),true,true,66).tyres().bottom()==368,"notifications lift the left column above their block wherever it sits");
        var twoDodge=SidebarLayout.arrange(split,true,true,0,new SidebarLayout.Sizes(190,190,190,190),true);
        CoreTests.check(twoDodge.phone().right()==568&&twoDodge.music().right()==568&&twoDodge.tyres().right()==633&&twoDodge.tyres().bottom()==344&&twoDodge.voltage().bottom()==310&&SidebarLayout.arrange(split.with(WidgetSettings.PHONE,false),true,false,0,new SidebarLayout.Sizes(190,190,190,190),true).tyres().bottom()==366,"during hill hold the left column rises above the cards pushed out of the right column and above the toast");
        var tall=WidgetSettings.DEFAULT.with(WidgetSettings.SPEED,true).with(WidgetSettings.POWER,true).withOrder(List.of(WidgetSettings.NOTIFICATIONS,WidgetSettings.PHONE,WidgetSettings.MUSIC,WidgetSettings.POWER,WidgetSettings.COLUMN_DIVIDER,WidgetSettings.VOLTAGE,WidgetSettings.SPEED,WidgetSettings.TYRES));
        var between=SidebarLayout.arrange(tall,true,true,66);
        CoreTests.check(between.power().right()==633&&between.power().bottom()==222&&between.speed().bottom()==312&&between.tyres().bottom()==132&&between.voltage().bottom()==402&&between.music().bottom()==368&&SidebarLayout.arrange(tall,true,true,0).power().right()==838&&SidebarLayout.arrange(tall,true,true,0).power().top()==260,"a card pushed out of the right column slots into the left column by height, between the cards above and below it, and returns once the column is short enough");
