        CoreTests.check(normal.music().height()==84&&normal.voltage().height()==84&&normal.tyres().height()==28&&normal.tyres().top()==316&&normal.voltage().top()==384&&SidebarLayout.INSTRUMENT.bottom()==254,"playing music is 68 high, the chart voltage 84 and the tyre line 28; the moved voltage card starts at the left column bottom");
        CoreTests.check(hidden.music()==null&&hidden.tyres().bottom()+6==hidden.phone().top()&&hidden.voltage().top()==316&&hidden.voltage().right()==838,"hidden music lets the tyre card drop by its height and gap and the voltage card returns to the right column");
        var noChart=SidebarLayout.arrange(WidgetSettings.DEFAULT.with(WidgetSettings.VOLTAGE_CHART,false),true,true,0);
