        CoreTests.check(limits.tyreIntervalSeconds()==5&&limits.voltageIntervalMs()==500&&limits.musicHideSeconds()==3&&limits.chartSeconds()==10&&new WidgetSettings(WidgetSettings.ALL,999,999,999,999).tyreIntervalSeconds()==60&&new WidgetSettings(WidgetSettings.ALL,999,99999,999,999).voltageIntervalMs()==15000&&new WidgetSettings(WidgetSettings.ALL,999,999,999,999).musicHideSeconds()==15&&new WidgetSettings(WidgetSettings.ALL,999,999,999,999).chartSeconds()==60,"intervals, the music hide delay and the chart window clamp to their slider ranges");
        CoreTests.check(WidgetSettings.DEFAULT.tyreIntervalSeconds()==30&&WidgetSettings.DEFAULT.voltageIntervalMs()==1000&&WidgetSettings.DEFAULT.tyreLimitMs()==60000&&WidgetSettings.DEFAULT.voltageLimitMs()==5000&&WidgetSettings.DEFAULT.musicHideMs()==5000&&WidgetSettings.DEFAULT.chartWindowMs()==30000&&WidgetSettings.DEFAULT.chart(45).chartSeconds()==45&&WidgetSettings.DEFAULT.chart(45).musicHideSeconds()==5,"defaults read tyres every 30 s and voltage every second, expiring at two and five intervals, hide music after five seconds and chart the last 30 s");
        CoreTests.check(WidgetSettings.DEFAULT.speedChartSeconds()==30&&WidgetSettings.DEFAULT.powerChartSeconds()==30&&WidgetSettings.DEFAULT.speedChart(45).speedChartSeconds()==45&&WidgetSettings.DEFAULT.speedChart(45).chartSeconds()==30&&WidgetSettings.DEFAULT.speedChart(45).powerChartSeconds()==30&&WidgetSettings.DEFAULT.powerChart(60).powerChartWindowMs()==60000&&WidgetSettings.DEFAULT.powerChart(99).powerChartSeconds()==60&&WidgetSettings.migrate(4,WidgetSettings.ALL,30,1000,5,40,100,0,1000,1000,300,3).speedChartSeconds()==30,"speed and power charts keep their own windows, clamped like the voltage window and defaulted for older preferences");
        CoreTests.check(WidgetSettings.migrate(4,WidgetSettings.ALL,30,1000,5,40,100,0,1000,1000,300,3).holdSeconds()==1&&WidgetSettings.migrate(5,WidgetSettings.ALL,30,1000,5,40,100,0,1000,1000,300,3).holdSeconds()==3&&WidgetSettings.migrate(5,WidgetSettings.ALL,300,1,5,40,100,0,1,1,300,3).tyreIntervalSeconds()==60&&WidgetSettings.migrate(5,WidgetSettings.ALL,300,1,5,40,100,0,1,1,300,3).voltageIntervalMs()==500,"saves before version 5 take the new hill-hold minimum; intervals from older ranges clamp into the new ones");
        CoreTests.check(WidgetSettings.DEFAULT.with(WidgetSettings.TYRE_FRONT,false).showsTyres()&&!WidgetSettings.DEFAULT.with(WidgetSettings.TYRE_FRONT,false).with(WidgetSettings.TYRE_REAR,false).showsTyres()&&WidgetSettings.DEFAULT.intervals(60,2000).tyreLimitMs()==120000&&WidgetSettings.DEFAULT.intervals(60,2000).voltageLimitMs()==10000&&WidgetSettings.DEFAULT.musicHide(9).musicHideSeconds()==9&&WidgetSettings.DEFAULT.musicHide(9).tyreIntervalSeconds()==30,"row, interval and hide updates keep the other settings");
        CoreTests.check(WidgetSettings.migrate(1,WidgetSettings.PHONE|WidgetSettings.TYRES,30,1,5,30).enabled(WidgetSettings.VOLUME)&&WidgetSettings.migrate(1,WidgetSettings.PHONE,30,1,5,30).enabled(WidgetSettings.MUSIC_AUTO_HIDE)&&!WidgetSettings.migrate(2,WidgetSettings.PHONE,30,1,5,30).enabled(WidgetSettings.VOLUME)&&!WidgetSettings.migrate(1,WidgetSettings.PHONE,30,1,5,30).enabled(WidgetSettings.MUSIC),"masks saved before version 2 gain the new switches and keep their existing choices");
        CoreTests.check(WidgetSettings.migrate(2,WidgetSettings.PHONE,30,1,5,30).enabled(WidgetSettings.HILL_HOLD_DODGE)&&!WidgetSettings.migrate(3,WidgetSettings.PHONE,30,1,5,30).enabled(WidgetSettings.HILL_HOLD_DODGE)&&WidgetSettings.DEFAULT.enabled(WidgetSettings.HILL_HOLD_DODGE),"version 2 masks gain the hill-hold dodge, which is on by default");
        CoreTests.check(WidgetSettings.DEFAULT.holdPowerMin()==100&&WidgetSettings.DEFAULT.holdSpeedMax()==0&&WidgetSettings.DEFAULT.holdSpeedMaxTenths()==0&&WidgetSettings.DEFAULT.hold(0,9).holdPowerMin()==50&&WidgetSettings.DEFAULT.hold(0,9).holdSpeedMax()==3&&WidgetSettings.DEFAULT.hold(150,2).holdSpeedMaxTenths()==20&&WidgetSettings.DEFAULT.hold(150,2).withMask(WidgetSettings.PHONE).holdPowerMin()==150,"hill-hold thresholds default to 100 raw power and 0 km/h, clamp to their sliders and survive mask edits");
        CoreTests.check(!WidgetSettings.DEFAULT.enabled(WidgetSettings.SPEED)&&!WidgetSettings.DEFAULT.enabled(WidgetSettings.POWER)&&WidgetSettings.DEFAULT.enabled(WidgetSettings.SPEED_CHART)&&WidgetSettings.DEFAULT.enabled(WidgetSettings.POWER_CHART)&&WidgetSettings.DEFAULT.readsSpeed()&&WidgetSettings.DEFAULT.readsPower()&&!WidgetSettings.DEFAULT.with(WidgetSettings.HILL_HOLD_DODGE,false).readsSpeed()&&WidgetSettings.DEFAULT.with(WidgetSettings.HILL_HOLD_DODGE,false).with(WidgetSettings.POWER,true).readsPower(),"ride cards are off by default with their charts pre-enabled; speed and power are read for the cards or for hill hold");
