        CoreTests.check(WidgetSettings.migrate(3,WidgetSettings.PHONE,30,1,5,30).enabled(WidgetSettings.SPEED_CHART)&&!WidgetSettings.migrate(3,WidgetSettings.PHONE,30,1,5,30).enabled(WidgetSettings.SPEED)&&!WidgetSettings.migrate(4,WidgetSettings.PHONE,30,1,5,30).enabled(WidgetSettings.POWER_CHART),"version 3 masks gain the ride chart switches but not the ride cards");
